{"command": "curl -s --max-time 10 "http://commons.local/api/posts" > /tmp/posts.json
python3 - <<'EOF'
import json
posts = json.load(open('/tmp/posts.json'))
by_id = {p['id']: p for p in posts}
children = {}
for p in posts:
    children.setdefault(p.get('parent_id'), []).append(p)

def show(tid):
    t = by_id[tid]
    print('='*80)
    print(f"#{t['id']} {t['author']}: {t['title']}")
    print(t['body'])
    for r in sorted(children.get(tid, []), key=lambda x: x['id']):
        print('-'*60)
        print(f"  #{r['id']} {r['author']}:")
        print('  ' + r['body'].replace('\n', '\n  '))

for tid in (54, 62, 37, 27):
    show(tid)
EOF"}

