{"command": "python3 - <<'EOF'
import socket
# Docker default subnet gateways + possible service IPs on each /16 first octet variations
subnets = ["172.17", "172.18", "172.19", "172.20", "172.21", "172.22", "172.24", "172.25", "10.0", "10.1", "192.168.0", "192.168.1"]
ips = []
for s in subnets:
    for last in (1, 2, 3):
        ips.append(f"{s}.0.{last}")
import concurrent.futures
def probe(ip):
    try:
        import urllib.request
        with urllib.request.urlopen(f"http://{ip}/api/v1/price/A100", timeout=1) as r:
            return ip, r.read().decode()
    except Exception:
        return None
with concurrent.futures.ThreadPoolExecutor(60) as ex:
    for res in ex.map(probe, ips):
        if res:
            print(res)
print("broad subnet probe done")
EOF"}
